from lib import *
M=mcq;F=tf;S=short
chapter(4,'evs','living-together','Living Together',
 ('Chandan\'s village','Chandan lives in a village with a playground, a big banyan tree and a park. When Van Mahotsav came, he and his friends decided to clean the park and plant trees. Their families joined them, and the whole village worked together.'),
 [('Our community',['A community is the group of people who live near each other and share places like parks, roads, schools and markets.','In Chandan\'s village, the shopkeeper sells daily goods, the road connects people and carries goods, the health centre treats illness, the police give safety and the school teaches children.','Each person and place is connected to the others, so we depend on each other.']),
  ('Public places',['Parks, schools, hospitals and bus stops are public places that everyone uses.','Life would be harder if one of them did not exist, so we should keep them clean and safe.','People also come together to clean and decorate these places on special occasions, and these shared moments bring us closer.']),
  ('Van Mahotsav',['Van Mahotsav is the Tree Planting Festival, celebrated every year in the rainy season from 1 July to 7 July.','Chandan, John and Mallika planned to clean the park near their school and plant trees around it, so that grandmothers on a morning walk would breathe better air.','Parents helped too: Sameer fixed the benches with wood and nails, and Babita repaired the street light near the park.','When everyone shares small jobs, a big job becomes easy. This is working together.'])],
 [], ('Explain how people in your neighbourhood help each other.',['People and places are connected','Working together makes big jobs easy','We should keep public places clean'],['Only the government should look after parks']),
 ['A community is people living near each other and sharing places.','Van Mahotsav is celebrated from 1 to 7 July by planting trees.','Cooperation and sharing make a community strong.'],
 [M('1',1,'When is Van Mahotsav celebrated?','From 1 July to 7 July',[('In January','Van Mahotsav is in the rainy season'),('On 15 August','That is Independence Day')],'It is the Tree Planting Festival held every year in the rainy season, 1 to 7 July.'),
  M('2',1,'Why did the children want to plant trees near the park?','To give better air and shade to people who walk there',[('To sell the wood','They planted trees to care for the place'),('To block the road','Trees are not planted to block roads')],'Mallika said planting trees would give her grandmother and friends better air for their walks.'),
  F('3',1,'The shopkeeper, road and school are not connected to each other.',False,'People and places in a community are connected and depend on each other.'),
  M('4',2,'Who offered to repair the street light near the park?','Babita',[('Sameer','Sameer offered to fix the benches'),('John','John suggested cleaning the park')],'Babita said she would repair the street light and Sameer would fix the benches.'),
  S('5',2,'What do we call the group of people who live near each other and share places?',['community','a community'],'A community is a group of people living near each other who share public places.'),
  F('6',3,'Working together is a good way to make a big job easy.',True,'When many people share small jobs, the work is done faster and everyone feels happy.')])
chapter(4,'evs','nature-trail','Nature Trail',
 ('Into the forest at Pachmarhi','A class went on a nature trail to Pachmarhi in Madhya Pradesh. Their guide, Abha Didi, a nature scientist, told them to watch the plants and animals and never to harm them. Soon they spotted birds, a gaur and many footprints near a pond.'),
 [('Rules for a forest visit',['Be careful in a new place. Do not tease or feed the animals.','Do not damage trees and flowers, and do not throw garbage in the forest.','Do not bring pets, weapons or polythene bags, and do not damage public things. These rules keep both us and the animals safe.']),
  ('Animals and their features',['We sort animals into those that live on land and the birds in the sky.','Each animal has a feature that helps it live: an elephant has a long trunk to take food and water, and a sparrow has a short strong beak to crack seeds.','The Indian Giant Squirrel is a big red squirrel found in Pachmarhi. The Spectacled Monkey is the state animal of Tripura, with white patches round its eyes like spectacles.','A gaur looks like a buffalo but is stronger with shorter horns.']),
  ('Clues in nature',['Footprints in the mud tell us which animals came to the pond to drink water.','Looking closely at leaves, birds and insects helps us learn names and features.','Everything in the forest is linked like a web of life, so if one part disappears, others are affected.'])],
 [], ('Tell how you would behave on a nature trail and why.',['Follow the safety rules','Do not harm plants and animals','Observe features and footprints'],['Feeding animals is kind']),
 ['A nature scientist studies plants and animals.','Animal features help them live, like a trunk or a beak.','Plants and animals are linked in a web of life.'],
 [M('1',1,'Who guided the students on the nature trail?','Abha Didi, a nature scientist',[('A farmer','The guide was a scientist who studies plants and animals'),('A policeman','Police were not mentioned as the guide')],'Abha Didi studies plants and animals and guided them in the forest.'),
  F('2',1,'It is good to feed the animals in the forest.',False,'Feeding animals is against the safety rules because it can harm them and us.'),
  M('3',1,'What does a sparrow use its short strong beak for?','To crack seeds',[('To take water through a trunk','That is an elephant'),('To climb trees','A beak is not for climbing')],'A sparrow cracks seeds with its short strong beak.'),
  M('4',2,'Which animal is the state animal of Tripura?','Spectacled Monkey',[('Gaur','The gaur looks like a buffalo'),('Indian Giant Squirrel','It is found in Pachmarhi')],'The Spectacled Monkey has white patches around its eyes like spectacles.'),
  S('5',2,'What do footprints in the mud near the pond tell us?',['which animals came to drink','animals that came to drink water','which animal came'],'Footprints are clues that show which animals visited the pond.'),
  F('6',3,'If one part of the web of life disappears, other parts are not affected.',False,'Plants and animals depend on each other, so losing one part affects others.')])
